suppressPackageStartupMessages({library(ggtern);library(ggplot2);library(grid);library(jsonlite)})
root<-normalizePath(commandArgs(TRUE)[1]);mode<-basename(root);d<-read.csv(file.path(root,'input.csv'));d$stage<-factor(d$stage,c('Young','Older'));stopifnot(nrow(d)==108,all(abs(d$T+d$L+d$R-1)<1e-12),max(abs(d$score-100*(d$T+.45*d$R)))<1e-10)
base<-ggtern(d,aes(x=L,y=T,z=R))+Tlab('Temporal')+Llab('Lymphoid')+Rlab('Repair')+theme_bw(base_family='Arial',base_size=8)+theme_showarrows()+theme_nomask()+theme(text=element_text(family='Arial',size=8),tern.axis.title=element_text(size=8),tern.axis.text=element_text(size=7),tern.axis.arrow=element_line(linewidth=.25),tern.panel.grid.major=element_line(colour='#D4D7D9',linewidth=.2),tern.panel.grid.minor=element_blank(),tern.axis.title.T=element_text(colour='#8B1A1A',face='plain'),tern.axis.title.L=element_blank(),tern.axis.title.R=element_blank(),legend.position='right',legend.text=element_text(size=7),legend.title=element_text(size=7),plot.margin=margin(5,7,5,18,'mm'),panel.background=element_rect(fill='white',colour=NA),plot.background=element_rect(fill='white',colour=NA))
if(mode=='ternary-groups')p<-base+geom_point(aes(fill=stage,shape=stage),size=2.1,stroke=.25,colour='#30343B')+scale_fill_manual(values=c(Young='#3B82B8B8',Older='#EF8848B8'),name='Age group')+scale_shape_manual(values=c(Young=21,Older=24),name='Age group')
if(mode=='ternary-continuous')p<-base+geom_point(aes(fill=score),shape=21,size=2.1,stroke=.25,colour='#30343B')+scale_fill_viridis_c(option='mako',direction=-1,name='Response\nscore',guide=guide_colourbar(display='rectangles'))
if(mode=='ternary-density')p<-base+stat_density_tern(aes(fill=after_stat(level)),geom='polygon',bins=8,alpha=.30,colour=NA)+scale_fill_viridis_c(option='cividis',name='Density',guide=guide_colourbar(display='rectangles'))+geom_mask()+theme_showmask()+geom_point(aes(colour=stage,shape=stage),size=2,stroke=.4,fill='white')+scale_colour_manual(values=c(Young='#2F6EA5',Older='#D95F4E'),name='Age group')+scale_shape_manual(values=c(Young=22,Older=24),name='Age group')
# Outer viewport provides a real page margin for ggtern corner text that extends
# beyond its own panel. The native simplex remains equilateral, never image-resized.
render<-function(){grid.newpage();pushViewport(viewport(x=.52,y=.50,width=.94,height=.94));grid.draw(ggtern::ggplotGrob(p));popViewport()}
ragg::agg_png(file.path(root,'figure.png'),width=150,height=115,units='mm',res=400,background='white');render();dev.off()
quartz(type='pdf',file=file.path(root,'figure.pdf'),width=150/25.4,height=115/25.4,family='Arial');render();dev.off()
svglite::svglite(file.path(root,'figure.svg'),width=150/25.4,height=115/25.4,bg='white');render();dev.off()
write_json(list(canvas_mm=c(150,115),observations=nrow(d),closure_max_error=max(abs(d$T+d$L+d$R-1)),groups=as.list(setNames(as.integer(table(d$stage)),levels(d$stage))),score_formula_error=max(abs(d$score-100*(d$T+.45*d$R))),font='Arial',minimum_declared_pt=7,mode=mode,vertex_mapping=list(left='L',top='T',right='R'),padding='native plot plus outer 94 percent viewport; PDF text bounds separately checked',input_changed=FALSE),file.path(root,'geometry.json'),auto_unbox=TRUE,pretty=TRUE);writeLines(capture.output(sessionInfo()),file.path(root,'environment.txt'));cat('TERNARY_RENDER_OK\n')
